# Initially generated by GitHub Copilot.
"""Helpers to wire dedicated-page links in common template rows."""

from mb_cmn import template_names as tmpln
from author import mp_cmn_rows_core as rows_core
from author_util import author

_KQ_SPECIAL_NAME = author.hbo("מ:כו״ק מיוחד")
_DUALCANT_NAME = author.hbo("מ:כפול")
_TWO_ACCENTS_ABBREV = "שני טעמים ..."


def _replace_obj_in_lists(node, old_obj, new_obj):
    if not isinstance(node, list):
        return
    for i, item in enumerate(node):
        if item == old_obj:
            node[i] = new_obj
            continue
        _replace_obj_in_lists(item, old_obj, new_obj)


def _normalize_two_accents_abbrev_title_scope():
    """Move dotted-underline affordance from full label to ellipsis suffix only."""
    old_obj = author.hbo(
        _TWO_ACCENTS_ABBREV,
        {"title": tmpln.TWO_ACCENTS_OF_QUPO},
    )
    new_obj = author.hbo_with_ellipsis_title(
        _TWO_ACCENTS_ABBREV,
        tmpln.TWO_ACCENTS_OF_QUPO,
    )
    for row in rows_core.ACCENT_ROWS:
        _replace_obj_in_lists(row, old_obj, new_obj)


_normalize_two_accents_abbrev_title_scope()


def with_kq_special_dedicated_page_link(kq_rows, *, doc_name: str):
    """Return k/q rows with מ:כו״ק מיוחד pointing to the caller-provided page."""
    out_rows = []
    for tmpl_cell, purpose in kq_rows:
        if tmpl_cell != _KQ_SPECIAL_NAME:
            out_rows.append([tmpl_cell, purpose])
            continue

        out_rows.append(
            [
                tmpl_cell,
                [
                    "Special $ketiv_qere. See ",
                    author.anchor_h("its dedicated page", doc_name),
                    ".",
                ],
            ]
        )

    return out_rows


def with_dualcant_dedicated_page_link(accent_rows, *, doc_name: str):
    """Return accent rows with מ:כפול pointing to the caller-provided page."""
    out_rows = []
    for tmpl_cell, purpose in accent_rows:
        if tmpl_cell != _DUALCANT_NAME:
            out_rows.append([tmpl_cell, purpose])
